# Function to find seeds (non-3 non-zero values at center of diamonds)
def find_seeds(grid):
    seeds = []
    for r in range(grid.shape[0]):
        for c in range(grid.shape[1]):
            val = grid[r,c]
            if val != 0 and val != 3:
                # Check if it's a diamond center
                if (grid[r-1,c] == 3 and grid[r+1,c] == 3 and 
                    grid[r,c-1] == 3 and grid[r,c+1] == 3):
                    seeds.append((r, c, val))
    return seeds

