def apply_transform(input_grid):
    out = np.zeros_like(input_grid)

    # Step 1: Mark frame cells (3s that are part of diamonds)
    frame_cells = set()
    for r in range(input_grid.shape[0]):
        for c in range(input_grid.shape[1]):
            if input_grid[r,c] == 3:
                if (input_grid[r-1,c] == 3 or input_grid[r+1,c] == 3) and \
                   (input_grid[r,c-1] == 3 or input_grid[r,c+1] == 3):
                    frame_cells.add((r,c))

    # Initialize with frame cells
    for r,c in frame_cells:
        out[r,c] = 3

    # Step 2: Apply fills
    # First pass: horizontal fills
    for r, c, s_val in seeds:
        for cc in range(input_grid.shape[1]):
            if (r, cc) not in frame_cells:
                out[r, cc] = s_val

    # Second pass: vertical fills (these override horizontal)
    for r, c, s_val in seeds:
        for rr in range(input_grid.shape[0]):
            if (rr, c) not in frame_cells:
                out[rr, c] = s_val

    return out

